  let w0 = 255 - w2 - w3; // 地表/基底兜底，四通道恒和 255

  // 3) 温度 / 湿度（海拔递减 + 低频气候噪声）
  let temp = clamp(
    0.5 + 0.3 * macro.detailNoise.noise2D(wx * 0.004 + 501.7, wz * 0.004 - 303.1) - Math.max(0, y) * 0.006,
    0, 1,
  );
