          const duY = u === 1 ? 1 : 0;
          const duZ = u === 2 ? 1 : 0;
          const dwX = w === 0 ? 1 : 0;
          const dwY = w === 1 ? 1 : 0;
          const dwZ = w === 2 ? 1 : 0;
          const occ = (uu, ww) => (solid(getPadded(
            bx + duX * uu + dwX * ww,
            by + duY * uu + dwY * ww,
            bz + duZ * uu + dwZ * ww,
          )) ? 1 : 0);
