          const s1d = occ(-1, 0);
          const s2u = occ(0, 1);
          const s2d = occ(0, -1);
          const cuu = occ(1, 1);
          const cud = occ(1, -1);
          const cdu = occ(-1, 1);
          const cdd = occ(-1, -1);
