          maskAO[n * 4 + 0] = vertexAO(s1d, s2d, cdd);
          maskAO[n * 4 + 1] = vertexAO(s1u, s2d, cud);
          maskAO[n * 4 + 2] = vertexAO(s1u, s2u, cuu);
          maskAO[n * 4 + 3] = vertexAO(s1d, s2u, cdu);
