      const a = b.a;
      const bb = b.b;
      const col = b.color || [0.7, 1.0, 1.6];
      const width = (b.width != null ? b.width : 0.09) / 2;
      const dx = bb[0] - a[0];
      const dy = bb[1] - a[1];
      const dz = bb[2] - a[2];
      const len = Math.hypot(dx, dy, dz) || 1e-4;
      const ux = dx / len;
      const uy = dy / len;
      const uz = dz / len;
