      const wx = a[0] - eye[0];
      const wy = a[1] - eye[1];
      const wz = a[2] - eye[2];
      let sx = uy * wz - uz * wy;
      let sy = uz * wx - ux * wz;
      let sz = ux * wy - uy * wx;
