        const hw = width;
        push(a[0] - q[0] * hw, a[1] - q[1] * hw, a[2] - q[2] * hw, col[0], col[1], col[2], 0.95);
        push(a[0] + q[0] * hw, a[1] + q[1] * hw, a[2] + q[2] * hw, col[0], col[1], col[2], 0.95);
        push(bb[0] + q[0] * hw, bb[1] + q[1] * hw, bb[2] + q[2] * hw, col[0], col[1], col[2], 0.35);
        push(a[0] - q[0] * hw, a[1] - q[1] * hw, a[2] - q[2] * hw, col[0], col[1], col[2], 0.95);
        push(bb[0] + q[0] * hw, bb[1] + q[1] * hw, bb[2] + q[2] * hw, col[0], col[1], col[2], 0.35);
        push(bb[0] - q[0] * hw, bb[1] - q[1] * hw, bb[2] - q[2] * hw, col[0], col[1], col[2], 0.35);
