      const hy = getSurfaceHeight(this.sw, d.x, d.z);
      const y = (hy >= 0 ? hy + 1 : (d.y != null ? d.y : 0)) + 0.05;
      const grow = clamp(d.t != null ? d.t : 1, 0, 1);
      const rr = r * (0.25 + 0.75 * grow);
