          pool.x[p] = pool.x[last]; pool.y[p] = pool.y[last]; pool.z[p] = pool.z[last];
          pool.vx[p] = pool.vx[last]; pool.vy[p] = pool.vy[last]; pool.vz[p] = pool.vz[last];
          pool.life[p] = pool.life[last]; pool.life0[p] = pool.life0[last];
